create table xxcus.xxcmp_alert_rules (
    alert_rule_id         number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by
    1 cache 20 noorder nocycle nokeep noscale not null enable,
    rule_code             varchar2(30 byte) not null enable,
    rule_name             varchar2(240 byte) not null enable,
    alert_type            varchar2(30 byte) not null enable,
    days_before           number default 0 not null enable,
    risk_tier             varchar2(30 byte),
    recipient_role_code   varchar2(30 byte),
    notify_flag           varchar2(1 byte) default 'Y' not null enable,
    start_review_flag     varchar2(1 byte) default 'N' not null enable,
    enabled_flag          varchar2(1 byte) default 'Y' not null enable,
    description           varchar2(1000 byte),
    created_by            varchar2(255 byte) not null enable,
    creation_date         timestamp(6) not null enable,
    last_updated_by       varchar2(255 byte) not null enable,
    last_update_date      timestamp(6) not null enable,
    last_update_login     varchar2(255 byte),
    object_version_number number default 1 not null enable
);

alter table xxcus.xxcmp_alert_rules
    add constraint xxcmp_alert_rules_ck1
        check ( alert_type in ( 'REVIEW_DUE', 'REVIEW_OVERDUE', 'SLA_BREACH', 'DOCUMENT_EXPIRY', 'ADVERSE_SCREENING' ) ) enable;

alter table xxcus.xxcmp_alert_rules
    add constraint xxcmp_alert_rules_ck2
        check ( notify_flag in ( 'Y', 'N' ) ) enable;

alter table xxcus.xxcmp_alert_rules
    add constraint xxcmp_alert_rules_ck3
        check ( start_review_flag in ( 'Y', 'N' ) ) enable;

alter table xxcus.xxcmp_alert_rules
    add constraint xxcmp_alert_rules_ck4
        check ( enabled_flag in ( 'Y', 'N' ) ) enable;

alter table xxcus.xxcmp_alert_rules
    add constraint xxcmp_alert_rules_ck5 check ( days_before >= 0 ) enable;

alter table xxcus.xxcmp_alert_rules
    add constraint xxcmp_alert_rules_pk primary key ( alert_rule_id )
        using index enable;

alter table xxcus.xxcmp_alert_rules add constraint xxcmp_alert_rules_uk1 unique ( rule_code )
    using index enable;


